record Features(int countLastMinute, double amountZScore, boolean newBeneficiary) {}

@Component
class FeatureWindow {

    private final StringRedisTemplate redis;

    Features observe(AuthorizationRequested e) {
        String key = "acct:" + e.accountId();
        // Rolling minute: a sorted set trimmed by score, so the window moves
        // with the clock rather than with a scheduled job.
        long now = e.occurredAt().toEpochMilli();
        redis.opsForZSet().add(key + ":t", String.valueOf(now), now);
        redis.opsForZSet().removeRangeByScore(key + ":t", 0, now - 60_000);
        redis.expire(key + ":t", Duration.ofMinutes(5));

        int count = redis.opsForZSet().zCard(key + ":t").intValue();
        return new Features(count, zScoreOf(key, e.amountMinor()), isNew(key, e.beneficiaryId()));
    }
}

@Component
class Scorer {

    private final OrtSession session;   // loaded once, reused per event
    private final Timer timer;

    double score(Features f) {
        return timer.record(() -> {
            var input = OnnxTensor.createTensor(env, new float[][] {{
                f.countLastMinute(), (float) f.amountZScore(), f.newBeneficiary() ? 1f : 0f
            }});
            try (var result = session.run(Map.of("input", input))) {
                return ((float[][]) result.get(0).getValue())[0][0];
            }
        });
    }
}

sealed interface Decision {
    record Allow()               implements Decision {}
    record Review(String reason) implements Decision {}
    record Block(String rule)    implements Decision {}
}

Decision decide(Payment p, Features f, double score) {
    // Rules first, and they are the only thing that can block.
    for (Rule rule : rules) {
        var hit = rule.evaluate(p);
        if (hit.isPresent()) return new Block(hit.get());
    }
    // The model can only ask a human to look. It cannot decline a payment.
    return score >= reviewThreshold
        ? new Review("score %.3f model %s".formatted(score, modelVersion))
        : new Allow();
}

// The narrative explains a decision that has already been made. It is
// attached to the case, and nothing downstream reads it back.
String narrate(Decision.Review review, Features f, Payment p) {
    var prompt = """
        Write two sentences for a fraud analyst reviewing this payment.
        State what is unusual and what to check. Do not recommend a decision.

        amount: %d %s
        payments from this account in the last minute: %d
        amount z-score against this account history: %.2f
        beneficiary seen before: %s
        """.formatted(p.amountMinor(), p.currency(),
                      f.countLastMinute(), f.amountZScore(),
                      f.newBeneficiary() ? "no" : "yes");
    return llm.complete(prompt);
}

